def bfs_at_depth(graph, start, target_depth):
    """Perform BFS and return nodes at exactly target_depth from start."""
    if target_depth == 0:
        return []  # Don't return start node per instructions

    from collections import deque

    # (node, depth)
    queue = deque([(start, 0)])
    visited = {start}
    nodes_at_target_depth = set()

    while queue:
        node, depth = queue.popleft()

        # If we've reached target depth, collect nodes
        if depth == target_depth:
            nodes_at_target_depth.add(node)
            # Don't expand further from target depth nodes
            continue

        # If we're below target depth, continue exploring
        if depth < target_depth:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, depth + 1))

    return sorted(list(nodes_at_target_depth))

